H,W=30,8
markers=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
g=[[8]*W for _ in range(H)]
for r,c in markers:g[r][c]=7
for r in range(H):
    cs=sorted(c for rr,c in markers if rr==r)
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):g[r][c]=3
for c in range(W):
    rs=sorted(r for r,cc in markers if cc==c)
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):g[r][c]=3
print('\n'.join(str(row) for row in g))
